using UnityEngine;

namespace CosmicShore.Gameplay
{
    /// <summary>
    /// The Space element's SQUARES animation on the omni crystal's body: the artist's three shape keys on the
    /// body's 60 square plates (<c>CrystalsRaw_V2.blend</c>, <c>OmniCrystal.001</c>, Action.008) and the frame
    /// weights that play them - a 4.8 s loop in which the squares turn about the pentagons, then weave over the
    /// triangles. <see cref="CrystalSpaceSquares"/> adds the keys to the body's runtime twin as blend shapes and
    /// plays the weights.
    ///
    /// GENERATED by <c>Tools/Build/author_omni_crystal_triangles.py</c> from
    /// <c>Docs/Studios/data/omni_space_squares.json</c> (baked out of the .blend by
    /// <c>Tools/Build/bake_omni_space_squares.py</c>); its <c>--check</c> fails if the asset drifts. Positions are
    /// in the body mesh's own space (the FBX's control points with x negated, as Unity imports them).
    ///
    /// JS twin: <c>squaresWeights()</c> in <c>Docs/Studios/OmniShepardLab.html</c>. Change one, change both.
    /// </summary>
    [CreateAssetMenu(fileName = "OmniSpaceSquares", menuName = "ScriptableObjects/Crystals/Space Squares")]
    public class CrystalSpaceSquaresSO : ScriptableObject
    {
        /// <summary>One shape key: every anchor's offset when the key is at 1. A key stacked on another
        /// (Blender's "relative to") is measured from that key at 1, and is only ever played with it at 1.</summary>
        [System.Serializable]
        public class Key
        {
            [Tooltip("The shape key's name in the .blend; the blend shape is added under this name.")]
            [SerializeField] string name;

            [Tooltip("The key this one is relative to (Blender's 'Relative To'), as an index into Keys; -1 = the Basis.")]
            [SerializeField] int stackedOn = -1;

            [Tooltip("Per anchor, its offset at weight 1, in the body mesh's space.")]
            [SerializeField] Vector3[] deltas;

            public string Name => name;
            public int StackedOn => stackedOn;
            public Vector3[] Deltas => deltas;
        }

        [Header("Shape")]
        [Tooltip("The body's control points the keys move (the square plates' corners), in the body mesh's space. A runtime body vertex at an anchor's position moves with it.")]
        [SerializeField] Vector3[] anchors;

        [Tooltip("The body mesh's radius these anchors were measured at (its farthest control point). A body imported at another scale is matched by the ratio.")]
        [SerializeField, Min(0f)] float bodyRadius;

        [SerializeField] Key[] keys;

        [Header("Playback")]
        [Tooltip("Every frame's key weights, frame-major (frame 0's keys, then frame 1's ...): the Bezier curves of Action.008 as Blender evaluates them.")]
        [SerializeField] float[] weights;

        [Tooltip("The action's frame rate. 25 in the art file.")]
        [SerializeField, Min(1f)] float framesPerSecond = 25f;

        [Tooltip("Playback rate: 1 = the art file's speed (a 4.8 s loop).")]
        [SerializeField, Range(0.25f, 3f)] float playbackSpeed = 1f;

        public Vector3[] Anchors => anchors;
        public float BodyRadius => bodyRadius;
        public Key[] Keys => keys;
        public int FrameCount => keys is { Length: > 0 } && weights != null ? weights.Length / keys.Length : 0;

        /// <summary>One loop, in seconds, at the playback speed.</summary>
        public float LoopSeconds => FrameCount / (framesPerSecond * playbackSpeed);

        /// <summary>
        /// Every key's weight (0..1) at <paramref name="seconds"/> into the loop: Blender's per-frame values,
        /// interpolated between frames EXCEPT across a snap - a key that jumps by more than half between two frames
        /// (the rotate key dropping 1 -> 0 as the weave begins, every key at the loop's end) holds its frame's
        /// values, because the squares land congruent there and a blend through the jump would sweep them across
        /// the body.
        /// </summary>
        public void WeightsAt(float seconds, float[] into)
        {
            int nk = keys.Length, frames = FrameCount;
            float fp = Mathf.Repeat(seconds * framesPerSecond * playbackSpeed, frames);
            int i0 = Mathf.Min((int)fp, frames - 1), i1 = (i0 + 1) % frames;
            float a = fp - i0;
            for (int k = 0; k < nk; k++)
                if (Mathf.Abs(weights[i1 * nk + k] - weights[i0 * nk + k]) > 0.5f) a = 0f;
            for (int k = 0; k < nk; k++)
                into[k] = Mathf.Lerp(weights[i0 * nk + k], weights[i1 * nk + k], a);
        }
    }
}
